use datom_codec::{Actualizing,Budget,Potential}; use std::{env,io::{Read,Write},os::unix::net::UnixStream}; use shared_translator::{FrameReading,FrameWriting,Restorable,Signal,Signalizable};
fn budget()->Budget{Budget{remaining:1_000_000,reader:protos::ReaderBudget{remaining:1_000_000},depth:0,maximum_depth:1024}}
fn main()->Result<(),Box<dyn std::error::Error>>{let mut a=env::args().skip(1);let socket=a.next().ok_or("META_SOCKET")?;let text=a.next().ok_or("DATOM")?;let mut p=Potential::<meta_signal_herdr_nexus::Query>::from(text);let q=p.actualize(&mut budget()).map_err(|e| format!("{e:?}"))?;let mut s=UnixStream::connect(socket)?;s.write_frame(&q.signalize()?,shared_translator::FrameCapacity::default())?;let body=s.read_frame(shared_translator::FrameCapacity::default())?;let r:meta_signal_herdr_nexus::Response=Signal::from(Vec::from(body)).restore()?;println!("{}",shared_translator::encode(&r));if !matches!(r,meta_signal_herdr_nexus::Response::Configured(meta_signal_herdr_nexus::ConfigureOutcome::Succeeded)){std::process::exit(1)}Ok(())}
